self.KB_CONTENT["card:750955"]={"id":"card:750955","ty":"card","sourceId":"750955","title":"『結帳單建立作業』中的『』為何？","ver":"iGP","topic":"結帳單","keywords":["結帳單","單別","異動","單號"],"y":"other","answer":"結帳單號 (TA002)* 若此單別之編碼方式為自動編號者，輸入單別後跳至異動日期欄位。* 若單別之編碼方式為「手動編號」須自行輸入不可空白，其餘自動預設單據資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
